import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../environments/environment';
import { firstValueFrom } from 'rxjs';

const base = () => `${environment.apiUrl}/admin`;

@Injectable({ providedIn: 'root' })
export class AdminService {
  constructor(private http: HttpClient) {}

  stats() { return firstValueFrom(this.http.get<any>(`${base()}/stats`)); }

  // generic helpers per resource
  list(resource: string) { return firstValueFrom(this.http.get<any[]>(`${base()}/${resource}`)); }
  create(resource: string, data: any) { return firstValueFrom(this.http.post<any>(`${base()}/${resource}`, data)); }
  update(resource: string, id: number, data: any) { return firstValueFrom(this.http.put<any>(`${base()}/${resource}/${id}`, data)); }
  remove(resource: string, id: number) { return firstValueFrom(this.http.delete<any>(`${base()}/${resource}/${id}`)); }
}
